// Extract Months
// Returns every month tab (newest first) plus defaultMonth — the newest month
// that actually has rows, so the dashboard opens on real data instead of an
// empty tab that was created ahead of time.
const cfg = $('Build Month Probe URLs').first().json;
const months = cfg.months || [];

const hasContent = (row) =>
  (row || []).some((v) => v !== null && v !== undefined && String(v).trim() !== '');

// batchGet returns valueRanges in the order the ranges were requested.
const populated = (response, requested) => {
  const ranges = ((response && response.valueRanges) || []);
  const filled = new Set();
  requested.forEach((month, index) => {
    const values = (ranges[index] && ranges[index].values) || [];
    if (values.some(hasContent)) filled.add(month);
  });
  return filled;
};

const projectFilled = populated($('HTTP - Project Month Probe').first().json, cfg.projectMonths || []);
const checklistFilled = populated($('HTTP - Checklist Month Probe').first().json, cfg.checklistMonths || []);

const withRecords = months.filter((m) => projectFilled.has(m) || checklistFilled.has(m));

const now = new Date();
const currentMonth = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;

if (months.length === 0) {
  return [{ json: { months: [currentMonth], monthsWithRecords: [], defaultMonth: currentMonth } }];
}

return [
  {
    json: {
      months,
      monthsWithRecords: withRecords,
      // Newest month with rows; if nothing has rows yet, fall back to the newest tab.
      defaultMonth: withRecords[0] || months[0],
    },
  },
];

// Config — resolve the requested month and carry the spreadsheet ids forward.
const PROJECT_SHEET_ID = '1ufjBTwjHbz3ki6Jz8Rumh43ixaKigwTJLOnLFaJEDxg';
const CHECKLIST_SHEET_ID = '1qmEgQdIqyEyWzJmAoEu_uS_0Gd5NRcMfX7RjHhlyzOc';

const query = ($input.first().json || {}).query || {};
const now = new Date();
const fallback = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
const asked = String(query.month || '').trim();
const month = /^\d{4}-\d{2}$/.test(asked) ? asked : fallback;

return [{ json: { month, PROJECT_SHEET_ID, CHECKLIST_SHEET_ID } }];

// Build Values URLs — pick the best tab in each spreadsheet for the requested month.
const cfg = $('Config').first().json;

const titlesOf = (meta) =>
  ((meta && meta.sheets) || [])
    .map((s) => (s && s.properties && s.properties.title) || '')
    .map((t) => String(t).trim())
    .filter(Boolean);

// Exact month tab wins. Otherwise the newest month tab that is not in the future.
// Otherwise the newest month tab at all. Otherwise the first tab in the file.
const tabOf = (meta, label) => {
  const titles = titlesOf(meta);
  if (titles.length === 0) throw new Error(`Could not read tab names from the ${label} spreadsheet`);
  if (titles.includes(cfg.month)) return cfg.month;
  const monthTabs = titles.filter((t) => /^\d{4}-\d{2}$/.test(t)).sort();
  if (monthTabs.length === 0) return titles[0];
  const past = monthTabs.filter((t) => t < cfg.month);
  return past.length > 0 ? past[past.length - 1] : monthTabs[monthTabs.length - 1];
};

const urlOf = (id, tab) =>
  `https://sheets.googleapis.com/v4/spreadsheets/${id}/values/${encodeURIComponent(`'${tab}'!A1:Z5000`)}` +
  `?valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER&majorDimension=ROWS`;

const projectTab = tabOf($('HTTP - Project Sheet Meta').first().json, 'IT Project Tracker');
const checklistTab = tabOf($('HTTP - Checklist Sheet Meta').first().json, 'Dashboard Tracker');

return [
  {
    json: {
      month: cfg.month,
      projectTab,
      checklistTab,
      projectMatched: projectTab === cfg.month,
      checklistMatched: checklistTab === cfg.month,
      projectUrl: urlOf(cfg.PROJECT_SHEET_ID, projectTab),
      checklistUrl: urlOf(cfg.CHECKLIST_SHEET_ID, checklistTab),
    },
  },
];

// Build Tracker Payload
// Joins "IT Project Tracker" (one row per dashboard) with "Dashboard Tracker"
// (one row per checklist item) and emits the exact shape src/api/tracker.js validates.

const cfg = $('Build Values URLs').first().json;
const projectRows = ($('HTTP - Project Rows').first().json || {}).values || [];
const checklistRows = ($('HTTP - Checklist Rows').first().json || {}).values || [];

/* ---------- text helpers ---------- */

const norm = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();
const key = (v) => norm(v).toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
const slug = (v) => key(v).replace(/ /g, '-');
const pad = (n) => String(n).padStart(2, '0');
const pct = (done, total) => (total > 0 ? Math.round((100 * done) / total) : 0);

// Sheet users type these to mean "nothing here".
const BLANKS = new Set(['', 'none', 'n a', 'na', 'nil', 'nan', 'null', 'tbd', 'to be decided', '-', '_']);
const isBlank = (v) => BLANKS.has(key(v));
const text = (v) => (isBlank(v) ? '' : norm(v));

/* ---------- header matching (typo tolerant) ---------- */

const distance = (a, b) => {
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i += 1) {
    const row = [i];
    for (let j = 1; j <= b.length; j += 1) {
      row[j] = Math.min(prev[j] + 1, row[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = row;
  }
  return prev[b.length];
};

const headerMap = (row) => {
  const map = {};
  (row || []).forEach((h, i) => {
    const k = key(h);
    if (k && !(k in map)) map[k] = i;
  });
  return map;
};

// Resolves a column by any of the given aliases: exact -> substring -> near-miss
// (so "Dahboard Name" still resolves to "Dashboard Name").
const col = (map, ...names) => {
  const headers = Object.keys(map);
  const wanted = names.map(key).filter(Boolean);
  for (const want of wanted) if (want in map) return map[want];
  for (const want of wanted) {
    const hit = headers.find((h) => h.includes(want) || want.includes(h));
    if (hit !== undefined) return map[hit];
  }
  for (const want of wanted) {
    const flat = want.replace(/ /g, '');
    const hit = headers.find((h) => {
      const hf = h.replace(/ /g, '');
      return distance(hf, flat) <= Math.max(1, Math.floor(flat.length / 6));
    });
    if (hit !== undefined) return map[hit];
  }
  return -1;
};

const cell = (row, index) => (index < 0 ? '' : text((row || [])[index]));
const raw = (row, index) => (index < 0 ? undefined : (row || [])[index]);

/* ---------- status vocabulary ----------
   These labels must stay in sync with src/lib/status.js (KNOWN) and
   src/lib/filter.js (MIX_BUCKET) or the front end will grey-pill them
   and the filtered KPI counts will drift from the unfiltered ones. */

const ITEM_STATUS = {
  approved: 'Approved',
  approve: 'Approved',
  accepted: 'Approved',
  completed: 'Completed',
  complete: 'Completed',
  done: 'Completed',
  delivered: 'Completed',
  closed: 'Completed',
  'in progress': 'In Progress',
  inprogress: 'In Progress',
  ongoing: 'In Progress',
  wip: 'In Progress',
  started: 'In Progress',
  'on hold': 'On Hold',
  hold: 'On Hold',
  holded: 'On Hold',
  paused: 'On Hold',
  blocked: 'On Hold',
  stopped: 'On Hold',
  pending: 'Pending',
  waiting: 'Pending',
  awaited: 'Pending',
  'yet to start': 'Not Started',
  'under review': 'Under Review',
  review: 'Under Review',
  'in review': 'Under Review',
  'not started': 'Not Started',
  notstarted: 'Not Started',
  'not stared': 'Not Started',
  'to do': 'Not Started',
  todo: 'Not Started',
  open: 'Not Started',
};

// Project-level status is collapsed to the four labels the front end charts.
const PROJECT_STATUS = {
  Approved: 'Completed',
  Completed: 'Completed',
  'In Progress': 'In Progress',
  'On Hold': 'On Hold',
  Pending: 'On Hold',
  'Under Review': 'On Hold',
  'Not Started': 'Not Started',
};

const itemStatus = (value) => {
  const k = key(value);
  if (!k || isBlank(value)) return null;
  return ITEM_STATUS[k] || norm(value);
};

const projectStatus = (value) => {
  const label = itemStatus(value);
  if (!label) return null;
  return PROJECT_STATUS[label] || 'On Hold';
};

// Must mirror bucketOf() in src/lib/filter.js.
const bucket = (label) => {
  const k = key(label);
  if (k === 'completed' || k === 'approved') return 'completed';
  if (k === 'in progress') return 'inProgress';
  if (k === 'on hold') return 'onHold';
  return 'notStarted';
};

const emptyMix = () => ({ completed: 0, inProgress: 0, onHold: 0, notStarted: 0 });

/* ---------- stages ----------
   Must stay in sync with STAGES in src/lib/status.js. "Data Collection"
   is folded into "Client Contact" because the front end only renders four steps. */

const STAGE = {
  'client contact': 'Client Contact',
  contact: 'Client Contact',
  requirement: 'Client Contact',
  requirements: 'Client Contact',
  'data collection': 'Client Contact',
  'data gathering': 'Client Contact',
  development: 'Development',
  dev: 'Development',
  build: 'Development',
  'in development': 'Development',
  'client review': 'Client Review',
  review: 'Client Review',
  uat: 'Client Review',
  testing: 'Client Review',
  maintenance: 'Maintenance',
  maintainance: 'Maintenance',
  support: 'Maintenance',
  handover: 'Maintenance',
  live: 'Maintenance',
};

const stageOf = (value) => {
  const k = key(value);
  if (!k || isBlank(value)) return null;
  return STAGE[k] || norm(value);
};

/* ---------- dates ---------- */

const iso = (value) => {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number' && isFinite(value)) {
    if (value <= 0) return null;
    const date = new Date(Math.round((value - 25569) * 86400000));
    return isNaN(date.getTime()) ? null : date.toISOString().slice(0, 10);
  }
  const t = norm(value);
  if (!t || isBlank(t)) return null;
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(t);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/.exec(t); // DD/MM/YYYY
  if (m) return `${m[3]}-${pad(m[2])}-${pad(m[1])}`;
  m = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2})$/.exec(t);
  if (m) return `20${m[3]}-${pad(m[2])}-${pad(m[1])}`;
  const d = new Date(t);
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
};

const earliest = (dates) => dates.filter(Boolean).sort()[0] || null;
const latest = (dates) => dates.filter(Boolean).sort().slice(-1)[0] || null;

const monthOf = (value) => {
  const t = norm(value);
  if (!t || isBlank(t)) return null;
  if (/^\d{4}-\d{1,2}/.test(t)) {
    const parts = t.split('-');
    return `${parts[0]}-${pad(parts[1])}`;
  }
  const d = iso(value);
  return d ? d.slice(0, 7) : null;
};

/* ---------- column resolution ---------- */

const pHead = headerMap(projectRows[0]);
const P = {
  client: col(pHead, 'client', 'client name', 'business', 'company'),
  dashboard: col(pHead, 'dashboard name', 'dahboard name', 'dashboard', 'project'),
  employee: col(pHead, 'assigned to', 'employee', 'handled by', 'owner'),
  stage: col(pHead, 'stage'),
  status: col(pHead, 'status', 'project status'),
  pending: col(pHead, 'pending with', 'pending'),
  follow: col(pHead, 'follow up status', 'follow up', 'followup'),
  start: col(pHead, 'start date'),
  delivery: col(pHead, 'delivery date', 'end date'),
  notes: col(pHead, 'notes', 'note'),
  remarks: col(pHead, 'remarks', 'remark', 'comment'),
  month: col(pHead, 'month'),
};

const cHead = headerMap(checklistRows[0]);
const C = {
  client: col(cHead, 'client', 'client name', 'business', 'company'),
  employee: col(cHead, 'assigned to', 'employee', 'handled by', 'owner'),
  dashboard: col(cHead, 'dashboard name', 'dahboard name', 'dashboard', 'project'),
  type: col(cHead, 'item type', 'type', 'category'),
  item: col(cHead, 'requirement checklist item', 'checklist item', 'requirement', 'item', 'task'),
  data: col(cHead, 'data status'),
  build: col(cHead, 'dashboard status', 'build status'),
  final: col(cHead, 'final status'),
  start: col(cHead, 'start date'),
  delivery: col(cHead, 'delivery date', 'end date'),
  remarks: col(cHead, 'remarks', 'remark', 'notes', 'comment'),
  month: col(cHead, 'month'),
};

const month = cfg.month;
// Only applies when the sheet actually has a Month column; the tab name is the
// primary month selector.
const keeps = (row, index) => {
  if (index < 0) return true;
  const value = monthOf(raw(row, index));
  return value === null ? true : value === month;
};
const hasContent = (row) => (row || []).some((v) => !isBlank(v));

/* ---------- join ---------- */

const projects = new Map();
const joinKey = (client, dashboard) => `${key(client)}|${key(dashboard)}`;

const ensure = (client, dashboard) => {
  const clientName = norm(client);
  const dashboardName = norm(dashboard);
  if (!clientName || !dashboardName) return null;
  const jk = joinKey(clientName, dashboardName);
  if (!projects.has(jk)) {
    const clientId = slug(clientName);
    projects.set(jk, {
      id: `${clientId}--${slug(dashboardName)}`,
      clientId,
      client: clientName,
      dashboard: dashboardName,
      employee: '',
      stage: null,
      stageRaw: null,
      status: null,
      statusRaw: null,
      pendingWith: null,
      followUp: null,
      notes: null,
      startDate: null,
      deliveryDate: null,
      fromProjectSheet: false,
      items: [],
    });
  }
  return projects.get(jk);
};

for (const row of projectRows.slice(1)) {
  if (!hasContent(row) || !keeps(row, P.month)) continue;
  const project = ensure(cell(row, P.client), cell(row, P.dashboard));
  if (!project) continue;
  project.fromProjectSheet = true;
  project.employee = cell(row, P.employee) || project.employee;
  project.stageRaw = cell(row, P.stage) || project.stageRaw;
  project.stage = stageOf(cell(row, P.stage)) || project.stage;
  project.statusRaw = cell(row, P.status) || project.statusRaw;
  project.status = projectStatus(cell(row, P.status)) || project.status;
  project.pendingWith = text(cell(row, P.pending)) || project.pendingWith;
  project.followUp = cell(row, P.follow) || project.followUp;
  project.notes = cell(row, P.notes) || cell(row, P.remarks) || project.notes;
  project.startDate = iso(raw(row, P.start)) || project.startDate;
  project.deliveryDate = iso(raw(row, P.delivery)) || project.deliveryDate;
}

for (const row of checklistRows.slice(1)) {
  if (!hasContent(row) || !keeps(row, C.month)) continue;
  const label = cell(row, C.item);
  if (!label) continue; // blank / "None" placeholder rows
  const project = ensure(cell(row, C.client), cell(row, C.dashboard));
  if (!project) continue;
  if (!project.employee) project.employee = cell(row, C.employee);

  const dataStatus = itemStatus(cell(row, C.data));
  const buildStatus = itemStatus(cell(row, C.build));
  const finalStatus = itemStatus(cell(row, C.final));
  const gates = [
    dataStatus === 'Approved' || dataStatus === 'Completed',
    buildStatus === 'Completed',
    finalStatus === 'Completed',
  ];
  const gatesPassed = gates.filter(Boolean).length;

  project.items.push({
    item: label,
    type: cell(row, C.type) || 'Other',
    dataStatus,
    buildStatus,
    finalStatus,
    startDate: iso(raw(row, C.start)),
    deliveryDate: iso(raw(row, C.delivery)),
    complete: gatesPassed === 3,
    gatesPassed,
    remarks: cell(row, C.remarks),
  });
}

/* ---------- derive ---------- */

// A dashboard that only exists in the checklist sheet still gets a sensible status.
const inferStatus = (items) => {
  if (items.length === 0) return 'Not Started';
  if (items.every((i) => i.complete)) return 'Completed';
  if (items.some((i) => i.gatesPassed > 0)) return 'In Progress';
  return 'Not Started';
};

const projectList = [...projects.values()]
  .map((project) => {
    const items = project.items;
    const itemsTotal = items.length;
    const itemsDone = items.filter((i) => i.complete).length;
    const gate = (test) => [items.filter(test).length, itemsTotal];
    const status = project.status || inferStatus(items);
    return {
      id: project.id,
      clientId: project.clientId,
      client: project.client,
      dashboard: project.dashboard,
      employee: project.employee || 'Unassigned',
      stage: project.stage,
      stageRaw: project.stageRaw,
      status,
      statusRaw: project.statusRaw || status,
      pendingWith: project.pendingWith,
      followUp: project.followUp,
      notes: project.notes,
      startDate: project.startDate || earliest(items.map((i) => i.startDate)),
      deliveryDate: project.deliveryDate || latest(items.map((i) => i.deliveryDate)),
      itemsDone,
      itemsTotal,
      completionPct: pct(itemsDone, itemsTotal),
      gates: {
        data: gate((i) => i.dataStatus === 'Approved' || i.dataStatus === 'Completed'),
        build: gate((i) => i.buildStatus === 'Completed'),
        signoff: gate((i) => i.finalStatus === 'Completed'),
      },
      items,
    };
  })
  .sort((a, b) => a.client.localeCompare(b.client) || a.dashboard.localeCompare(b.dashboard));

const clientMap = new Map();
for (const project of projectList) {
  if (!clientMap.has(project.clientId)) {
    clientMap.set(project.clientId, {
      id: project.clientId,
      name: project.client,
      handledBy: [],
      dashboardCount: 0,
      itemsDone: 0,
      itemsTotal: 0,
      completionPct: 0,
      statusMix: emptyMix(),
    });
  }
  const entry = clientMap.get(project.clientId);
  entry.dashboardCount += 1;
  entry.itemsDone += project.itemsDone;
  entry.itemsTotal += project.itemsTotal;
  entry.statusMix[bucket(project.status)] += 1;
  if (!entry.handledBy.includes(project.employee)) entry.handledBy.push(project.employee);
}
const clients = [...clientMap.values()]
  .map((entry) => ({ ...entry, handledBy: entry.handledBy.sort(), completionPct: pct(entry.itemsDone, entry.itemsTotal) }))
  .sort((a, b) => a.name.localeCompare(b.name));

const employeeMap = new Map();
for (const project of projectList) {
  if (!employeeMap.has(project.employee)) {
    employeeMap.set(project.employee, {
      name: project.employee,
      projectCount: 0,
      clientCount: 0,
      completionPct: 0,
      itemsDone: 0,
      itemsTotal: 0,
      statusMix: emptyMix(),
      projects: [],
      clientIds: new Set(),
    });
  }
  const entry = employeeMap.get(project.employee);
  entry.projectCount += 1;
  entry.itemsDone += project.itemsDone;
  entry.itemsTotal += project.itemsTotal;
  entry.statusMix[bucket(project.status)] += 1;
  entry.clientIds.add(project.clientId);
  entry.projects.push({
    clientId: project.clientId,
    client: project.client,
    projectId: project.id,
    dashboard: project.dashboard,
    status: project.status,
  });
}
const employees = [...employeeMap.values()]
  .map(({ clientIds, ...rest }) => ({
    ...rest,
    clientCount: clientIds.size,
    completionPct: pct(rest.itemsDone, rest.itemsTotal),
  }))
  .sort((a, b) => a.name.localeCompare(b.name));

// Mirrors the recount in filterTracker() so filtered and unfiltered KPIs agree.
const mix = projectList.reduce((acc, project) => {
  acc[bucket(project.status)] += 1;
  return acc;
}, emptyMix());

return [
  {
    json: {
      schemaVersion: 1,
      month,
      sourceMonth: { project: cfg.projectTab, checklist: cfg.checklistTab },
      generatedAt: new Date().toISOString(),
      kpis: {
        totalClients: clients.length,
        totalProjects: projectList.length,
        activeProjects: mix.inProgress + mix.onHold,
        inProgress: mix.inProgress,
        notStarted: mix.notStarted,
        onHold: mix.onHold,
        completed: mix.completed,
      },
      employees,
      clients,
      projects: projectList,
    },
  },
];

// Build Month Probe URLs
// Lists every YYYY-MM tab, then asks both spreadsheets for the first few rows of
// each one so we can tell which months actually contain records.
const PROJECT_SHEET_ID = '1ufjBTwjHbz3ki6Jz8Rumh43ixaKigwTJLOnLFaJEDxg';
const CHECKLIST_SHEET_ID = '1qmEgQdIqyEyWzJmAoEu_uS_0Gd5NRcMfX7RjHhlyzOc';

const titlesOf = (meta) =>
  ((meta && meta.sheets) || [])
    .map((s) => (s && s.properties && s.properties.title) || '')
    .map((t) => String(t).trim())
    .filter(Boolean);

const projectTitles = titlesOf($('HTTP - Months Meta').first().json);
const checklistTitles = titlesOf($('HTTP - Checklist Months Meta').first().json);

const isMonth = (t) => /^\d{4}-\d{2}$/.test(t);
const months = [...new Set([...projectTitles, ...checklistTitles].filter(isMonth))].sort().reverse();

// A2:C400 skips the header row, so a tab with only headers probes as empty.
const rangesFor = (titles) =>
  months
    .filter((m) => titles.includes(m))
    .map((m) => `ranges=${encodeURIComponent(`'${m}'!A2:C400`)}`);

const batchUrl = (id, titles) => {
  const ranges = rangesFor(titles);
  // No month tabs in this file: probe a single harmless cell so the HTTP node
  // still returns a valid (empty) response instead of a 400.
  const query = ranges.length > 0 ? ranges.join('&') : `ranges=${encodeURIComponent('A1:A1')}`;
  return (
    `https://sheets.googleapis.com/v4/spreadsheets/${id}/values:batchGet?${query}` +
    `&valueRenderOption=UNFORMATTED_VALUE&majorDimension=ROWS`
  );
};

return [
  {
    json: {
      months,
      projectMonths: months.filter((m) => projectTitles.includes(m)),
      checklistMonths: months.filter((m) => checklistTitles.includes(m)),
      projectProbeUrl: batchUrl(PROJECT_SHEET_ID, projectTitles),
      checklistProbeUrl: batchUrl(CHECKLIST_SHEET_ID, checklistTitles),
    },
  },
];
